from reportlab.platypus import SimpleDocTemplate,Paragraph,Spacer,Table,TableStyle,PageBreak
from reportlab.lib.styles import getSampleStyleSheet,ParagraphStyle
from reportlab.lib import colors
from reportlab.pdfbase import pdfmetrics
from reportlab.pdfbase.ttfonts import TTFont
from pathlib import Path
base=Path('/home/fafa/Documentos/ServiNow');out=base/'output/pdf/ServiNow-guia-para-exponer.pdf'
for name,file in [('Regular','DejaVuSans.ttf'),('Bold','DejaVuSans-Bold.ttf')]:pdfmetrics.registerFont(TTFont(name,'/usr/share/fonts/TTF/'+file))
pdfmetrics.registerFontFamily('Regular',normal='Regular',bold='Bold')
blue=colors.HexColor('#165FB8');navy=colors.HexColor('#193254');light=colors.HexColor('#EFF5FC')
s=getSampleStyleSheet()
s.add(ParagraphStyle(name='BodyCustom',fontName='Regular',fontSize=10,leading=15,textColor=navy,spaceAfter=9))
s.add(ParagraphStyle(name='TitleCustom',fontName='Bold',fontSize=27,leading=33,textColor=navy,spaceAfter=15))
s.add(ParagraphStyle(name='HeadCustom',fontName='Bold',fontSize=16,leading=21,textColor=blue,spaceBefore=12,spaceAfter=11))
s.add(ParagraphStyle(name='SmallCustom',fontName='Regular',fontSize=8.5,leading=12,textColor=navy,spaceAfter=5))
story=[]
def p(t,style='BodyCustom'): return Paragraph(t,s[style])
def add(t):story.append(p(t))
def h(t):story.append(p(t,'HeadCustom'))
def page():story.append(PageBreak())
def table(rows):
 t=Table([[p(a,'SmallCustom'),p(b,'SmallCustom')] for a,b in rows],colWidths=[145,350],hAlign='LEFT')
 t.setStyle(TableStyle([('BACKGROUND',(0,0),(-1,0),light),('VALIGN',(0,0),(-1,-1),'TOP'),('LINEBELOW',(0,0),(-1,0),1,blue),('LINEBELOW',(0,1),(-1,-1),.3,colors.HexColor('#D4DFEC')),('LEFTPADDING',(0,0),(-1,-1),9),('RIGHTPADDING',(0,0),(-1,-1),9),('TOPPADDING',(0,0),(-1,-1),7),('BOTTOMPADDING',(0,0),(-1,-1),7)]));story.append(t)
add('PROYECTO DE APLICACIONES MÓVILES · GUÍA DE EXPOSICIÓN')
story.append(p('ServiNow','TitleCustom'))
add('<b>Qué hicimos, qué utilizamos y cómo explicarlo</b>')
add('Integrantes: Santiago Dorado, Juan David Saza y Fabián López.<br/>Fecha: 11 de noviembre de 2026.')
h('1. ¿Qué es ServiNow?')
add('Es una aplicación Android que conecta a personas que necesitan un servicio con trabajadores que pueden realizarlo. El cliente publica su necesidad y los trabajadores presentan propuestas. Cuando se acepta una propuesta, ambas personas pueden coordinar el servicio mediante un chat privado.')
h('Presentación inicial para decir en voz alta')
add('“Nuestro proyecto se llama ServiNow. Lo desarrollamos para facilitar la búsqueda y contratación de servicios. Permite publicar trabajos, recibir propuestas, aceptar a un trabajador, conversar por chat y dar el servicio por finalizado. También incluye mapas, fotografías, avisos y una herramienta de inteligencia artificial para mejorar la descripción de las solicitudes.”')
h('2. Recorrido principal de la aplicación')
for x in ['1. El usuario se registra o inicia sesión.','2. El cliente crea una publicación con descripción, ubicación y, si lo desea, una fotografía.','3. La publicación pasa por revisión antes de aparecer para la comunidad.','4. Los trabajadores consultan las publicaciones y presentan propuestas.','5. El cliente acepta una propuesta y se habilita la conversación privada.','6. Al terminar el servicio, el cliente puede marcar el trabajo como finalizado.'] :add(x)
add('Además, la aplicación incluye perfiles, estadísticas, logros, avisos y funciones de moderación.')
page();h('3. Herramientas para construir la app')
table([('<b>Tecnología</b>','<b>Función en ServiNow</b>'),('Android Studio y Kotlin','Entorno de desarrollo y lenguaje con el que programamos la aplicación.'),('Jetpack Compose','Construcción de pantallas, formularios, botones, tarjetas y listas.'),('Navigation Compose','Navegación entre las pantallas y organización de sus destinos.'),('ViewModel y StateFlow','Administración del estado de las pantallas y actualización de la interfaz cuando cambian los datos.'),('Repositorios','Separación de las operaciones de datos respecto a la lógica de las pantallas.'),('Hilt','Inyección de dependencias: proporciona los componentes que necesitan otras clases.'),('Coil','Carga y visualización de fotografías dentro de la interfaz.'),('Recursos de Android','Textos en español e inglés y selección del idioma.'),('Git y GitHub','Control de versiones y almacenamiento del código fuente con su historial.')])
h('4. ¿Cómo organizamos el código?')
add('Utilizamos una organización por responsabilidades basada en MVVM y repositorios. La interfaz muestra la información; el ViewModel procesa las acciones y mantiene el estado; los repositorios leen o modifican los datos. Los modelos representan entidades como usuarios, publicaciones, propuestas y mensajes.')
add('<b>Flujo resumido:</b> Pantalla → ViewModel → Repositorio → Servicio de datos. Los cambios de estado regresan a la interfaz para mostrar la información actualizada.')
add('“Esta separación nos permite cambiar la forma de guardar datos sin tener que reescribir toda la pantalla. También facilita localizar errores y probar partes del proyecto.”')
page();h('5. Servicios externos utilizados')
table([('<b>Servicio</b>','<b>Para qué se utiliza</b>'),('Firebase Authentication','Registro, inicio de sesión con correo o Google y recuperación mediante un enlace seguro enviado al correo.'),('Cloud Firestore','Persistencia y sincronización de publicaciones, propuestas, perfiles, conversaciones y avisos entre usuarios.'),('Cloudinary','Almacenamiento de fotografías en la nube. Firestore conserva los enlaces de las imágenes.'),('Mapbox','Visualización del mapa y selección de la ubicación del trabajo.'),('OpenRouter','Acceso al modelo de IA que ayuda a mejorar las descripciones de los trabajos.'),('Cloudflare Workers','Ejecución de operaciones del servidor y protección de claves privadas de los servicios externos.'),('Firebase Cloud Messaging','Envío de notificaciones al dispositivo por mensajes y cambios relacionados con los trabajos.'),('Firebase App Distribution','Distribución del APK release a personas invitadas para probar la aplicación.')])
h('Ejemplo: ¿qué sucede al enviar un mensaje?')
add('“La pantalla comunica la acción al ViewModel. El repositorio guarda el mensaje en Firestore. La otra persona recibe el cambio en su conversación y el servidor solicita una notificación mediante Firebase Cloud Messaging.”')
h('Dos aclaraciones importantes')
add('<b>Fotos:</b> el archivo de la imagen se guarda en Cloudinary; en Firestore se guarda su URL. Así podemos recuperar y mostrar la fotografía desde distintos dispositivos.')
add('<b>Contraseñas:</b> Firebase Authentication administra las credenciales. Para recuperarlas se envía un enlace de restablecimiento; no enviamos la contraseña actual por correo.')
page();h('6. Mejoras y correcciones realizadas')
for a,b in [('Publicaciones y propuestas','Corregimos la consulta de información entre diferentes cuentas.'),('Fotografías','Arreglamos la carga a la nube y la visualización de imágenes en la aplicación.'),('Chat privado','Habilitamos la conversación entre el cliente y el trabajador después de aceptar una propuesta.'),('Inteligencia artificial','Mejoramos las instrucciones, las respuestas y el manejo de errores. La sugerencia se revisa antes de aplicarla al texto.'),('Notificaciones','Añadimos avisos internos, contador de pendientes y apertura de la pantalla relacionada al tocar un aviso.')]:add('<b>'+a+':</b> '+b)
h('7. ¿Cómo comprobamos el funcionamiento?')
add('Se registraron <b>55 pruebas unitarias de Android</b> y <b>27 pruebas del servidor</b> aprobadas. También se realizaron pruebas con servicios reales para imágenes, chat y notificaciones, incluyendo la recepción de un aviso con la app en segundo plano y la apertura del chat.')
add('En Firebase App Distribution aparecen dos pruebas de rastreo automatizadas superadas. Estos resultados corresponden a los recorridos ejecutados; no significan que todos los flujos posibles estén libres de errores ni sustituyen las pruebas manuales del equipo.')
h('8. Uso de inteligencia artificial')
add('<b>Durante el desarrollo:</b> usamos Codex como apoyo para implementar, revisar y corregir código. El equipo debe comprender los cambios, revisar lo generado y comprobar su funcionamiento.')
add('<b>Dentro de la aplicación:</b> OpenRouter permite que el usuario mejore la redacción de una solicitud. La IA no debe inventar precios, causas del problema ni condiciones que el usuario no haya indicado.')
add('“Son dos usos diferentes: una IA nos apoyó al desarrollar el proyecto y otra función de IA forma parte de la experiencia del usuario en ServiNow.”')
page();h('9. ¿Qué hicimos para entregar el APK?')
add('Generamos <b>ServiNow 1.1, código de versión 2</b>, como APK release. Esta es la versión preparada para distribuir, diferente de la versión debug utilizada durante el desarrollo.')
for x in ['1. Creamos una llave propia para firmar la aplicación.','2. Guardamos la llave y su contraseña fuera del repositorio.','3. Configuramos Gradle y activamos R8 para optimizar y reducir el código y los recursos no utilizados.','4. Registramos en Firebase la huella SHA-1 de la firma release para permitir el acceso con Google.','5. Generamos y verificamos el APK firmado.','6. Subimos el APK a Firebase App Distribution y agregamos el correo institucional como verificador.']:add(x)
add('<b>Estado de la distribución:</b> el correo juand.sazaa@uqvirtual.edu.co aparece como invitado. La aceptación y descarga dependen de que el usuario abra la invitación.')
h('Explicación breve para la exposición')
add('“No entregamos solamente el código. También generamos una versión instalable, firmada con una llave propia y optimizada con R8. La subimos a Firebase App Distribution para que los verificadores autorizados puedan descargarla y probarla.”')
h('10. Preguntas que pueden hacerles')
table([('<b>Pregunta</b>','<b>Respuesta breve</b>'),('¿Dónde están los datos?','En Cloud Firestore. Las fotografías están en Cloudinary y Firestore guarda sus enlaces.'),('¿Qué hace la IA?','Ayuda a redactar mejor las descripciones; el usuario conserva la decisión de aplicar la sugerencia.'),('¿Por qué usar ViewModel?','Para separar el estado y la lógica de la pantalla respecto a su representación visual.'),('¿Por qué firmar el APK?','La firma identifica la aplicación y permite que Android compruebe la continuidad de las actualizaciones.'),('¿Para qué sirve App Distribution?','Para entregar versiones de prueba a personas invitadas, sin publicarlas en Google Play.')])
page();h('11. Guion de cierre')
add('“En conclusión, ServiNow integra el flujo de publicación, propuestas y coordinación de servicios con herramientas reales en la nube. Utilizamos Firebase para autenticación y datos, Cloudinary para imágenes, Mapbox para mapas y OpenRouter para la ayuda de redacción. Organizamos el código con ViewModel y repositorios, realizamos pruebas y distribuimos un APK release mediante Firebase App Distribution.”')
h('Sugerencia para repartir la exposición')
add('<b>Integrante 1:</b> objetivo de ServiNow y demostración del recorrido cliente-trabajador.')
add('<b>Integrante 2:</b> arquitectura, tecnologías y servicios externos.')
add('<b>Integrante 3:</b> mejoras, pruebas, uso de IA y distribución del APK.')
add('Esta distribución es una sugerencia; los tres integrantes deben poder explicar el funcionamiento general y las decisiones del proyecto.')
h('Demostración recomendada')
add('Preparar dos cuentas de prueba. Mostrar una publicación, una propuesta aceptada, el chat y un aviso. Después enseñar el selector de idioma, una fotografía y la ayuda de IA. Cerrar mostrando la versión 1.1 (2) en App Distribution.')
add('Antes de exponer, comprobar la conexión a internet y el acceso a las cuentas. Evitar mostrar contraseñas, claves privadas o datos personales de otros usuarios.')
h('Referencias y evidencia del proyecto')
add('<b>Guía de generación del APK:</b><br/><link href="https://caflorezvi.github.io/guias-apps-moviles/21.generar-apk.html" color="#165FB8">caflorezvi.github.io/guias-apps-moviles/21.generar-apk.html</link>')
add('<b>Repositorio del proyecto:</b><br/><link href="https://github.com/JDFaFa/ServiNow" color="#165FB8">github.com/JDFaFa/ServiNow</link>')
add('<b>Firebase App Distribution:</b><br/><link href="https://console.firebase.google.com/project/servinow-4efcf/appdistribution/app/android:com.example.servinow/releases" color="#165FB8">Abrir versiones de ServiNow en Firebase</link> (requiere acceso autorizado).')
add('Esta guía resume el trabajo realizado y los resultados registrados en el proyecto. Sirve como apoyo para la exposición; no reemplaza la comprensión del código ni una revisión completa de la aplicación.')
