 c.setStrokeColor(blue);c.line(50,805,545,805);c.setFont('Regular',8);c.setFillColor(navy);c.drawString(50,28,'ServiNow · Guía para exponer · 11/11/2026');c.drawRightString(545,28,str(d.page))
